CREATE TABLE IF NOT EXISTS company (id TEXT PRIMARY KEY, nome TEXT, slug TEXT, primary_color TEXT, logo_url TEXT, telefone TEXT, status_cobranca TEXT, trial_ate TEXT, created_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, tipo_pessoa TEXT, cnpj_cpf TEXT, razao_social TEXT, nome_fantasia TEXT, inscricao_estadual TEXT, segmento TEXT, porte TEXT, site TEXT, email_corporativo TEXT, cep TEXT, rua TEXT, numero TEXT, complemento TEXT, bairro TEXT, cidade TEXT, estado TEXT, pais TEXT, onboarding_completed BOOLEAN DEFAULT 0, onboarding_step INTEGER DEFAULT 0, selected_plan_slug TEXT, financeiro_ativo BOOLEAN DEFAULT 0, financeiro_dias_vencimento_padrao INTEGER DEFAULT 7, creditos_saldo INTEGER DEFAULT 0, creditos_resetam_em TEXT, creditos_origem TEXT DEFAULT 'trial');
CREATE TABLE IF NOT EXISTS company_user (id TEXT PRIMARY KEY, user_id TEXT, company_id TEXT, role TEXT, ativo BOOLEAN DEFAULT 1, forcar_troca_senha BOOLEAN DEFAULT 0, convite_token TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, company_id));
CREATE TABLE IF NOT EXISTS user_roles (id TEXT PRIMARY KEY, user_id TEXT, role TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, role));
CREATE TABLE IF NOT EXISTS app_config (id TEXT PRIMARY KEY, super_admin_emails TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY, email TEXT, nome TEXT, nome_completo TEXT, cpf TEXT, cargo TEXT, telefone TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agent_config (id TEXT PRIMARY KEY, user_id TEXT, company_id TEXT, nome_agente TEXT, nome_empresa TEXT, papel_objetivo TEXT, estilo_comunicacao TEXT, sobre_empresa TEXT, produtos_servicos TEXT, pode_fazer TEXT, nao_pode_fazer TEXT, telefone_transferencia TEXT, palavra_pausar TEXT, palavra_despausar TEXT, segmento TEXT, descricao_negocio TEXT, diferenciais TEXT, publico_alvo TEXT, regiao_horario TEXT, ofertas TEXT, cupom TEXT, como_vender TEXT, objecoes TEXT, formas_pagamento TEXT, ticket_medio TEXT, faq TEXT, politicas TEXT, posvenda_msg TEXT, pedir_avaliacao BOOLEAN DEFAULT 0, reativar_cliente BOOLEAN DEFAULT 0, tom TEXT, horarios_atendimento TEXT, mensagem_fora_horario TEXT, responder_em_partes BOOLEAN DEFAULT 1, segundos_buffer INTEGER DEFAULT 8, personalidade TEXT, foco_atendimento TEXT, emoji_intensidade TEXT, usar_girias BOOLEAN DEFAULT 0, chamar_por_nome BOOLEAN DEFAULT 1, perguntar_uma_por_vez BOOLEAN DEFAULT 1, pode_brincar BOOLEAN DEFAULT 0, assinar_mensagens BOOLEAN DEFAULT 0, proatividade INTEGER DEFAULT 50, velocidade_resposta TEXT, evitar_palavras TEXT, idioma TEXT DEFAULT 'pt-BR', ai_provider TEXT, ai_model TEXT, openai_api_key TEXT, anthropic_api_key TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id));
CREATE TABLE IF NOT EXISTS whatsapp_instances (id TEXT PRIMARY KEY, user_id TEXT, company_id TEXT, instance_name TEXT, numero TEXT, status TEXT, webhook_token TEXT, webhook_configured_at TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id));
CREATE TABLE IF NOT EXISTS mensagens (id TEXT PRIMARY KEY, user_id TEXT, company_id TEXT, numero TEXT, contato_nome TEXT, direcao TEXT, autor TEXT, texto TEXT, whatsapp_message_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id, whatsapp_message_id));
CREATE TABLE IF NOT EXISTS crm_cards (id TEXT PRIMARY KEY, user_id TEXT, company_id TEXT, numero TEXT, nome TEXT, status TEXT, ultima_mensagem TEXT, ultima_em TEXT, observacao TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, stage_id TEXT, valor REAL, origem TEXT, owner_id TEXT, tags TEXT, proxima_acao TEXT, follow_up TEXT, utm_source TEXT, utm_medium TEXT, utm_campaign TEXT, UNIQUE(company_id, numero));
CREATE TABLE IF NOT EXISTS contact_pause (id TEXT PRIMARY KEY, user_id TEXT, company_id TEXT, numero TEXT, pausado BOOLEAN DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id, numero));
CREATE TABLE IF NOT EXISTS crm_stage (id TEXT PRIMARY KEY, company_id TEXT, nome TEXT, ordem INTEGER DEFAULT 0, cor TEXT, tipo TEXT DEFAULT 'normal', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS produto (id TEXT PRIMARY KEY, company_id TEXT, nome TEXT, preco REAL, descricao TEXT, ativo BOOLEAN DEFAULT 1, ordem INTEGER DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS lead_nota (id TEXT PRIMARY KEY, company_id TEXT, card_id TEXT, autor_id TEXT, texto TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS lead_evento (id TEXT PRIMARY KEY, company_id TEXT, card_id TEXT, tipo TEXT, descricao TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agendamento (id TEXT PRIMARY KEY, company_id TEXT, card_id TEXT, titulo TEXT, inicio TEXT, fim TEXT, google_event_id TEXT, status TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS google_integration (company_id TEXT PRIMARY KEY, email TEXT, access_token TEXT, refresh_token TEXT, expiry TEXT, calendar_id TEXT, conectado BOOLEAN DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS plan (id TEXT PRIMARY KEY, slug TEXT UNIQUE, nome TEXT, descricao TEXT, preco_cents INTEGER, moeda TEXT, intervalo TEXT, trial_days INTEGER, limite_mensagens INTEGER, limite_instancias INTEGER, limite_usuarios INTEGER, limite_contatos INTEGER, features TEXT, destaque BOOLEAN DEFAULT 0, ativo BOOLEAN DEFAULT 1, ordem INTEGER DEFAULT 0, paddle_product_id TEXT, paddle_price_id TEXT, stripe_product_id TEXT, stripe_price_id TEXT, checkout_url TEXT, creditos_mensais INTEGER DEFAULT 1000, creditos_trial INTEGER DEFAULT 100, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS subscription (id TEXT PRIMARY KEY, company_id TEXT UNIQUE, plan_id TEXT, status TEXT, provider TEXT, external_subscription_id TEXT, external_customer_id TEXT, buyer_email TEXT, current_period_start TEXT, current_period_end TEXT, trial_start TEXT, trial_end TEXT, canceled_at TEXT, cancel_at_period_end BOOLEAN DEFAULT 0, next_billing_amount_cents INTEGER, metadata TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS company_billing (id TEXT PRIMARY KEY, company_id TEXT UNIQUE, tipo_pessoa TEXT, cnpj_cpf TEXT, razao_social TEXT, nome_responsavel TEXT, email_cobranca TEXT, telefone TEXT, inscricao_estadual TEXT, cep TEXT, rua TEXT, numero TEXT, complemento TEXT, cidade TEXT, estado TEXT, pais TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS campaign (id TEXT PRIMARY KEY, company_id TEXT, created_by TEXT, nome TEXT, mensagem TEXT, media_url TEXT, status TEXT, agendado_para TEXT, filtro_tags TEXT, intervalo_min INTEGER, intervalo_max INTEGER, pausa_apos INTEGER, pausa_minutos INTEGER, total_destinatarios INTEGER DEFAULT 0, enviados INTEGER DEFAULT 0, falhas INTEGER DEFAULT 0, proximo_envio_em TEXT, iniciado_em TEXT, concluido_em TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS campaign_target (id TEXT PRIMARY KEY, campaign_id TEXT, company_id TEXT, contato_numero TEXT, contato_nome TEXT, status TEXT, enviado_em TEXT, erro TEXT, processing_token TEXT, processing_started_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS message_template (id TEXT PRIMARY KEY, company_id TEXT, user_id TEXT, atalho TEXT, texto TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS csat_response (id TEXT PRIMARY KEY, company_id TEXT, numero TEXT, contato_nome TEXT, token TEXT, score INTEGER, comentario TEXT, enviado_por TEXT, enviado_em TEXT, respondido_em TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, company_id TEXT, user_id TEXT, actor_email TEXT, acao TEXT, recurso TEXT, detalhes TEXT, ip TEXT, user_agent TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS webhook_endpoint (id TEXT PRIMARY KEY, company_id TEXT, nome TEXT, url TEXT, secret TEXT, eventos TEXT, ativo BOOLEAN DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS api_token (id TEXT PRIMARY KEY, company_id TEXT, label TEXT, token TEXT UNIQUE, criado_por TEXT, ultimo_uso_em TEXT, revogado BOOLEAN DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS webhook_delivery_log (id TEXT PRIMARY KEY, company_id TEXT, endpoint_id TEXT, evento TEXT, status_code INTEGER, erro TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS billing_event_log (id TEXT PRIMARY KEY, provider TEXT, event_type TEXT, external_id TEXT, buyer_email TEXT, matched_company_id TEXT, processed BOOLEAN DEFAULT 0, error TEXT, payload TEXT, event_key TEXT UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fin_categoria (id TEXT PRIMARY KEY, company_id TEXT, nome TEXT, tipo TEXT, cor TEXT, ativo BOOLEAN DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fin_lancamento (id TEXT PRIMARY KEY, company_id TEXT, categoria_id TEXT, card_id TEXT, tipo TEXT, descricao TEXT, valor REAL, vencimento TEXT, pagamento_em TEXT, status TEXT, competencia TEXT, observacao TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id, card_id));
CREATE TABLE IF NOT EXISTS credit_ledger (id TEXT PRIMARY KEY, company_id TEXT, delta INTEGER, saldo_apos INTEGER, motivo TEXT, ref TEXT, created_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);